-- TJ poster-override edges — resync the router graph to the poster-corrected
-- topology (db/data/topology.tj.overrides.ts) for the corridors the GTFS feed
-- gets wrong. APPLY LAST, after edges.sql and tj_edges_insert.sql:
--   wrangler d1 execute commute --remote --file=src/db/scripts/tj_poster_override_edges.sql
-- The DELETE clears each overridden corridor's stale adjacencies (which
-- INSERT OR REPLACE alone can't remove); the INSERTs rebuild them from the
-- poster topology. Distances are reused from the live edges table where the
-- adjacency already existed, else |Δ cumM| (haversine) for genuinely new edges.
DELETE FROM edges WHERE lineCode IN ('2', '2A', '3', '3F', '4', '4D', '5C', '6', '6A', '6B', '7F', '9A', '9C', '12', '14');
